const input = $input.first().json.body ?? $input.first().json;
const clean = (v, max = 2000) => String(v ?? '').trim().slice(0, max);
const name = clean(input.name, 120);
const email = clean(input.email, 254).toLowerCase();
const company = clean(input.company, 160);
const message = clean(input.message, 4000);
const errors = [];
if (!name) errors.push('Name is required.');
if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) errors.push('A valid email is required.');
if (!message) errors.push('Message is required.');
if (errors.length) return [{json:{success:false,statusCode:400,errors}}];
const text = message.toLowerCase();
const spamSignals = ['buy cheap','ignore all previous instructions','90% off','click here to win'];
const supportSignals = ['login is not working','cannot log in','can\'t log in','account access','already bought','already purchased','password reset','support'];
const questionSignals = ['opening hours','weekend hours','what are your hours','where are you located','how does it work'];
const buyingSignals = ['pricing','price','quote','budget','demo','demonstration','subscription','contract','purchase','buy','licenses','licences'];
let intent = 'other';
if (spamSignals.some(s => text.includes(s))) intent = 'spam';
else if (supportSignals.some(s => text.includes(s))) intent = 'support';
else if (buyingSignals.some(s => text.includes(s))) intent = 'buying';
else if (questionSignals.some(s => text.includes(s)) || text.trim().endsWith('?')) intent = 'question';
let ruleScore = 0;
if (company) ruleScore += 20;
if (/@(gmail|yahoo|outlook|hotmail)\\./i.test(email) === false) ruleScore += 15;
if (message.length > 80) ruleScore += 15;
const keywordCount = buyingSignals.filter(s => text.includes(s)).length;
ruleScore += Math.min(keywordCount * 10, 40);
ruleScore = Math.min(ruleScore, 100);
const caps = {buying:100,question:45,support:30,other:40,spam:10};
const baselineAI = intent === 'buying' ? 75 : intent === 'question' ? 20 : intent === 'support' ? 15 : intent === 'spam' ? 0 : 30;
const aiScore = Math.min(baselineAI, caps[intent] ?? 40);
const finalScore = Math.round(aiScore * 0.7 + ruleScore * 0.3);
const category = intent === 'spam' ? 'spam' : (intent === 'buying' && finalScore >= 65 ? 'hot' : 'nurture');
return [{json:{success:true,receivedAt:new Date().toISOString(),name,email,company,message,intent,urgency:intent==='buying'?'medium':'low',ruleScore,aiScore,finalScore,category,aiStatus:'baseline_only',summary:'Starter workflow baseline classification; connect an AI node for model-generated analysis.',suggestedReply:'Thank you for reaching out. Our team will review your message and follow up as appropriate.',errors:[]}}];
